/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        startDate,
        endDate
    } = api.context.props;
    const localeOutput = api.data.page_locale_parser_1.output;
    var href = `/now/conversation/analytics/users`;
    if (startDate && endDate) {
        href += `/params/start-date/${startDate}/end-date/${endDate}`;
    }
    const breadCrumbs = [{
            "label": localeOutput && localeOutput.breadcrumb || 'Back to Users',
            "href": href
        },
        {
            "label": localeOutput && localeOutput.user || ''
        }
    ];

    return breadCrumbs;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const localeOutput = api.data.page_locale_parser_1.output;
  const explore = localeOutput && localeOutput.explore || '';
	return "<div>" + explore + "</div>";
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const output = api.data.analytics_user_detail_1.output;
    const localeOutput = api.data.page_locale_parser_1.output;
    let firstSessionTime = '',
        lastSessionTime = '',
        duration = 0,
        hours = '',
        minutes = '',
        seconds = '';
    if (output) {
        firstSessionTime = output.FirstSessionTime && output.FirstSessionTime.$date || null;
        lastSessionTime = output.LastSessionTime && output.LastSessionTime.$date || null;
        duration = output.TotalDuration || 0;
        seconds = parseInt((duration / 1000) % 60),
            minutes = parseInt((duration / (1000 * 60)) % 60),
            hours = parseInt((duration / (1000 * 60 * 60)) % 24);
    }

    return [{
            "label": localeOutput && localeOutput.firstConversation || '',
            "value": {
                "type": "string",
                "value": firstSessionTime
            }
        },
        {
            "label": localeOutput && localeOutput.lastConversation || '',
            "value": {
                "type": "string",
                "value": lastSessionTime
            }
        },
        {
            "label": localeOutput && localeOutput.timeInChat || '',
            "value": {
                "type": "string",
                "value": duration > 0 ? String(hours).padStart(2, '0') + ':' + String(minutes).padStart(2, '0') + ':' + String(seconds).padStart(2, '0') : ''
            }
        }
    ];
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {

    const output = api.data.analytics_user_detail_1.output;
    const clients = output && output.Clients || [];
    const localeOutput = api.data.page_locale_parser_1.output;
    const languages = [];
    clients.forEach(function(client) {
        const clientLanguages = client.Languages || [];
        clientLanguages.forEach(function(clientLanguage) {
            if (clientLanguage && languages.indexOf(clientLanguage) === -1)
                languages.push(clientLanguage);
        });
    });

    return [{
        "label": localeOutput && localeOutput.languages,
        "value": {
            "type": "string",
            "value": languages.join()
        }
    }];
}

/**
 * @param {params} params 
 * @param {api} params.api 
 * @param {any} params.imports */
function evaluateProperty({
    api
}) {
    const output = api.data.analytics_user_detail_1.output;
    const localeOutput = api.data.page_locale_parser_1.output;
    let channels = "";
    if (output) {
        const clients = output.Clients || [];
        channels = "<div>" + clients.map(function(item) {
            return item.ChannelName;
        }).join() + "</div>";
    }
    return [{
        label: localeOutput && localeOutput.channels || '',
        value: {
            type: "html",
            value: channels
        }
    }];
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const output = api.data.analytics_user_detail_1.output;
    const customProperties = output && output.CustomProperties || {};
    const keysCollection = [];
    for (const key in customProperties) {
        const itemObject = {
            "label": key,
            "value": {
                "type": "string",
                "value": customProperties[key]
            }
        };
        keysCollection.push(itemObject);
    }
    return keysCollection;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    return JSON.stringify({
        "and": [{
            "UserAppIndex": {
                "eq": parseInt(api.context.props.userIndex)
            }
        }]
    });
}
